using Himma.Api.Infrastructure.Localization;
using static Himma.Api.Data.Seed.ExerciseSeedData;

namespace Himma.Api.Data.Seed;

/// <summary>
/// "How to do it" for each system exercise: start/end photos, numbered steps, a safety tip and the helper
/// muscles. Fixed content in code, like the workout templates; user exercises have no guide.
/// Photos: free-exercise-db (https://github.com/yuhonas/free-exercise-db), released into the public domain
/// (Unlicense), stored in wwwroot/assets/exercises/{MediaKey}/0.jpg (start) and 1.jpg (end).
/// </summary>
public sealed record ExerciseGuide(
    string? MediaKey,
    IReadOnlyList<string> HelperMuscles,
    IReadOnlyList<string> StepsAr,
    IReadOnlyList<string> StepsEn,
    string TipAr,
    string TipEn);

public static class ExerciseGuides
{
    /// <summary>Arabic and English names of the helper-muscle keys.</summary>
    private static readonly Dictionary<string, (string Ar, string En)> MuscleNames = new()
    {
        ["shoulders"] = ("الأكتاف", "Shoulders"),
        ["triceps"] = ("الترايسبس", "Triceps"),
        ["biceps"] = ("البايسبس", "Biceps"),
        ["forearms"] = ("الساعد", "Forearms"),
        ["chest"] = ("الصدر", "Chest"),
        ["glutes"] = ("المؤخرة", "Glutes"),
        ["hamstrings"] = ("الفخذ الخلفي", "Hamstrings"),
        ["quadriceps"] = ("الفخذ الأمامي", "Quadriceps"),
        ["calves"] = ("السمانة", "Calves"),
        ["lats"] = ("الظهر العريض", "Lats"),
        ["middleBack"] = ("وسط الظهر", "Middle back"),
        ["lowerBack"] = ("أسفل الظهر", "Lower back"),
        ["traps"] = ("الترابيس", "Traps"),
        ["abs"] = ("البطن", "Abs"),
    };

    public static string MuscleName(string key) =>
        MuscleNames.TryGetValue(key, out var name) ? Lang.T(name.Ar, name.En) : key;

    public static ExerciseGuide? Find(string arabicName) => All.GetValueOrDefault(arabicName);

    private static ExerciseGuide G(string? media, string[] helpers, string[] ar, string[] en, string tipAr, string tipEn) =>
        new(media, helpers, ar, en, tipAr, tipEn);

