        [LateralRaise] = G("lateral-raise", [],
            ["قف ودمبل بكل يد بجانبك، والمرفقان مثنيان قليلاً.", "ارفع يديك للجانبين حتى مستوى الكتفين.", "انزل ببطء."],
            ["Stand with a dumbbell in each hand at your sides, elbows slightly bent.", "Raise your arms out to the sides up to shoulder height.", "Lower slowly."],
