            ["Stand with the dumbbells in front of your thighs.", "Raise one (or both) in front of you to shoulder height.", "Lower slowly; alternate if doing one at a time."],
            "لا ترفع فوق مستوى الكتف، ولا تميل للخلف.", "Do not raise above shoulder height or lean back."),
        [ReverseFly] = G("reverse-fly", [],
