        [TricepsPushdown] = G("triceps-pushdown", [],
            ["قف أمام الكابل وامسك الحبل والمرفقان بجانب جسمك.", "ادفع الحبل للأسفل حتى تستقيم ذراعاك، وافتح طرفيه في الأسفل.", "ارجع ببطء والمرفقان ثابتان."],
            ["Stand facing the cable, hold the rope with your elbows at your sides.", "Push the rope down until your arms are straight, spreading the ends at the bottom.", "Return slowly with your elbows fixed."],
            "المرفقان ثابتان بجانب الجسم؛ لا تحركهما للأمام.", "Keep your elbows pinned to your sides; do not let them drift forward."),
        [OverheadExtension] = G("overhead-extension", [],
