        [SkullCrusher] = G("skull-crusher", ["forearms"],
            ["استلقِ على البنش والبار فوق صدرك والذراعان مستقيمتان.", "اثنِ مرفقيك ونزّل البار نحو جبهتك ببطء.", "مد ذراعيك وارجع البار لفوق."],
            ["Lie on the bench with the bar above your chest, arms straight.", "Bend your elbows and lower the bar slowly toward your forehead.", "Straighten your arms to bring it back up."],
