        [BenchDips] = G("bench-dips", ["chest", "shoulders"],
            ["اجلس على حافة البنش واليدان بجانب الحوض، ثم انزل للأمام.", "اثنِ مرفقيك وانزل حتى تقارب زاوية 90 درجة.", "ادفع بيديك حتى تستقيم ذراعاك."],
            ["Sit on the edge of a bench with your hands next to your hips, then slide forward off it.", "Bend your elbows and lower until they are near 90 degrees.", "Push back up until your arms are straight."],
