        [AlternatingCurl] = G("alternating-curl", ["forearms"],
            ["قف ودمبل بكل يد، والكفان متقابلان.", "ارفع دمبل واحد ولف كفك لفوق وأنت ترفع.", "انزل ببطء، ثم سوّها باليد الثانية."],
            ["Stand with a dumbbell in each hand, palms facing each other.", "Curl one dumbbell up, turning your palm up as you lift.", "Lower slowly, then do the other arm."],
