        // ---------- Abs ----------
        [Crunch] = G("crunch", [],
            ["استلقِ على ظهرك والركبتان مثنيتان واليدان خلف رأسك برفق.", "ارفع كتفيك عن الأرض بشد البطن.", "انزل ببطء بدون ما ترتاح كامل."],
            ["Lie on your back, knees bent, hands lightly behind your head.", "Lift your shoulders off the floor by tightening your abs.", "Lower slowly without fully relaxing."],
            "لا تسحب رقبتك بيديك؛ نظرك للسقف.", "Do not pull on your neck with your hands; look at the ceiling."),
        [HangingLegRaise] = G("hanging-leg-raise", [],
            ["تعلّق في العقلة والذراعان مستقيمتان.", "ارفع رجليك للأمام حتى توازي الأرض (أو اثنِ الركبتين للمبتدئ).", "انزل ببطء بدون تأرجح."],
            ["Hang from the bar with straight arms.", "Raise your legs in front of you to hip height (bend your knees if you are a beginner).", "Lower slowly without swinging."],
            "لا تتأرجح؛ الحركة من البطن مو من الزخم.", "Do not swing; the movement comes from your abs, not momentum."),
        [SidePlank] = G("side-plank", ["shoulders"],
            ["استلقِ على جنبك وارتكز على ساعد واحد والمرفق تحت الكتف.", "ارفع الحوض حتى يستقيم الجسم من الرأس للقدم.", "اثبت للمدة المطلوبة، ثم بدّل الجهة."],
            ["Lie on your side resting on one forearm, elbow under your shoulder.", "Lift your hips until your body is straight from head to feet.", "Hold for the set time, then switch sides."],
            "لا تخلي الحوض ينزل، وشد البطن طول الوقت.", "Do not let your hips drop; keep your abs tight throughout."),
        [CableCrunch] = G("cable-crunch", [],
            ["اركع أمام الكابل وامسك الحبل عند جانبي رأسك.", "اثنِ جذعك للأسفل بشد البطن حتى يقترب مرفقاك من ركبتيك.", "ارجع ببطء."],
            ["Kneel facing the cable and hold the rope beside your head.", "Curl your torso down by tightening your abs until your elbows near your knees.", "Return slowly."],
            "الحوض ثابت؛ الحركة من البطن مو من الوركين.", "Keep your hips still; the movement comes from your abs, not your hips."),
        [RussianTwist] = G("russian-twist", ["lowerBack"],
            ["اجلس والركبتان مثنيتان، ومِل للخلف قليلاً والظهر مستقيم.", "ارفع قدميك قليلاً عن الأرض (أو خلهما على الأرض للمبتدئ).", "لف جذعك يميناً ثم يساراً بتحكم."],
            ["Sit with your knees bent and lean back slightly with a straight back.", "Lift your feet a little off the floor (keep them down if you are a beginner).", "Rotate your torso to the right and to the left, under control."],
